INSERT INTO m244_art VALUES
(0,0,$m244$الديباجة$m244$,$m244$قانون رقم 120 لسنة 1982 بإصدار قانون تنظيم أعمال الوكالة التجارية وبعض أعمال الوساطة التجارية أو السمسرة العقارية
باسم الشعب رئيس الجمهورية قرر مجلس الشعب القانون الآتى نصه ، وقد أصدرناه :$m244$,'690668ad2306e7bbda1f482fbcc64c59'),
(1,-1,$m244$المادة الأولى إصدار$m244$,$m244$يعمل بأحكام القانون المرافق فى شأن تنظيم أعمال الوكالة التجارية وبعض أعمال الوساطة التجارية أو السمسرة العقارية .$m244$,'fde3e671dbdde78d39bd1befa6ed131b'),
(2,-1,$m244$المادة الثانية إصدار$m244$,$m244$تلغى القوانين أرقام 107 لسنة 1961 ببعض الأحكام الخاصة بتنظيم أعمال الوكالة التجارية و93 لسنة 1974 فى شأن حق المواطنين فى ممارسة تمثيل الشركات الأجنبية و117 لسنة 1975 فى شأن رسوم القيد فى سجلات أعمال الوكالة التجارية ، كما يلغى كل حكم يخالف أحكام القانون المرافق .$m244$,'ddda561cbecf88e95db5c687caa99b71'),
(3,-1,$m244$المادة الثالثة إصدار$m244$,$m244$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به بعد تسعة أشهر من تاريخ نشره .
يبصم هذا القانون بخاتم الدولة ، وينفذ كقانون من قوانينها ،
صدر برئاسة الجمهورية فى 6 شوال سنة 1402 (26 يوليه سنة 1982)$m244$,'2c7cf707bf66cbe90cb56421a9317950'),
(1,0,$m244$المادة 1$m244$,$m244$في تطبيق أحكام هذا القانون ، يقصد بالعبارات والكلمات الآتية المعاني المبينة قرين كل منها :
الوكيل التجاري : كل شخص طبيعي أو اعتباري يقوم بصفة معتادة ، دون أن يكون مرتبطا بعقد عمل أو عقد تأجير خدمات ، بتقديم العطاءات أو بإبرام عمليات الشراء أو البيع أو التأجير أو تقديم الخدمات باسم ولحساب المنتجين أو التجار أو الموزعين أو باسمه ولحساب أحد هؤلاء .
الوسيط التجاري : كل شخص طبيعي أو اعتباري اقتصر نشاطه ، ولو عن صفقة واحدة على البحث عن متعاقد أو التفاوض معه لإقناعه بالتعاقد ، وكذلك كل من قام بأي عمل من أعمال الوكالة التجارية ولو على غير اعتياد ولمرة واحدة ، أو كان مرتبطا مع المنتج أو التاجر أو الموزع بعقد عمل .
السمسار العقاري : كل من قيد بالسجل المنشأ لهذا الغرض ، ويقوم بأعمال السمسرة أو السعي لإبرام العقود المتعلقة بالعقارات والأراضي المبنية أو الفضاء ، سواء أعمال شرائها أو بيعها أو تأجيرها أو التوسط في شيء مما تقدم .
القوائم السلبية : قوائم الكيانات الإرهابية والإرهابيين المنظمة بموجب القانون رقم 8 لسنة 2015 في شأن تنظيم قوائم الكيانات الإرهابية والإرهابيين ، والأسماء والكيانات المدرجة بقاعدة البيانات لدي وحدة مكافحة غسل الأموال المنشأة بموجب قانون مكافحة غسل الأموال الصادر بالقانون رقم 80 لسنة 2002
الوزارة المختصة : الوزارة المعنية بشئون التجارة الخارجية .
الوزير المختص : الوزير المعني بشئون التجارة الخارجية .$m244$,'a62610fe85aac928dd303616032a812d'),
(2,0,$m244$المادة 2$m244$,$m244$مع عدم الإخلال بأحكام القانون رقم 34 لسنة 1976 في شأن السجل التجاري ، تحظر مزاولة أي عمل من أعمال الوكالة التجارية أو الوساطة التجارية أو السمسرة العقارية ، إلا لمن يكون اسمه مقيدا في سجل الوكلاء والوسطاء التجاريين أو السماسرة العقاريين ، بحسب الأحوال ، المعدين لذلك الغرض بالوزارة المختصة .$m244$,'c029b51c6e79facd18d50b036464ec31'),
(2,1,$m244$المادة 2 مكرراً$m244$,$m244$ينشأ بالوزارة المختصة سجل إلكتروني لقيد السماسرة العقاريين يسمي "سجل السمسرة العقارية" تدون فيه بيانات ومعلومات المقيدين بسجل مزاولة مهنة السمسرة العقارية ، بما فيها بياناتهم الشخصية الأساسية ، وبيانات محل مزاولتهم المهنة ، والكود الذي حصل عليه والفئة التي ينتمي إليها ، وغيرها من البيانات ، والمعلومات ، والإحصائيات اللازمة لتنظيم نشاط السمسرة العقارية .
وتجري الوزارة المختصة تحديثا للسجل المشار إليه بالفقرة الأولي من هذه المادة بشكل مستمر ومنتظم ، بما يتفق مع المستجدات في هذا النشاط ، وتنشر القائمة المحدثة للسماسرة العقاريين على مستوي الجمهورية على الموقع الإلكتروني لها بما يتيح للجميع الاطلاع عليها .
ولذوي الشأن الحصول على صورة مصدقة من المعلومات المقيدة في السجل المشار إليه بالفقرة الأولي من هذه المادة أو شهادة سلبية بعدم إدراج أمر معين فيه .
ويصدر الوزير المختص القرارات اللازمة لتنفيذ أحكام هذه المادة ، وتحديد فئات وأنواع السماسرة العقاريين الذين يدرجون بسجل السماسرة العقاريين .$m244$,'a0ec3df92b7a0d353b7c0b303bfe9fec'),
(3,0,$m244$المادة 3$m244$,$m244$يشترط فيمن يقيد أو يجدد قيده في سجل الوكلاء والوسطاء التجاريين المشار إليه في المادة (2) من هذا القانون ، الشروط الآتية :
أولا : بالنسبة إلى قيد الأشخاص الطبيعيين :
(أ) أن يكون مصرى الجنسية . وبالنسبة لمن تجنس بالجنسية المصرية يجب أن يكون قد مضى على اكتسابه هذه الجنسية عشر سنوات على الأقل .
(ب) أن يكون كامل الأهلية .
(ج) أن يكون حسن السمعة ، ولم يسبق الحكم عليه بعقوبة جناية أو بعقوبة مقيدة للحرية فى جريمة مخلة بالشرف أو الأمانة ، أو فى إحدى الجرائم المنصوص عليها فى هذا القانون أو قوانين الاستيراد ، أو التصدير ، أو النقد ، أو الجمارك ، أو الضرائب ، أو التموين ، أو الشركات ، أو التجارة ، ما لم يكن قد رد إليه اعتباره .
(د) ألا يكون قد أشهر إفلاسه ، ما لم يكن قد رد إليه اعتباره .
(هـ) ألا يكون من العاملين بالحكومة ووحدات الحكم المحلى والهيئات العامة وشركات ووحدات القطاع العام . ويشترط بالنسبة للعاملين السابقين فى هذه الجهات أن يكون قد مضى على تاريخ ترك الخدمة بالاستقالة أو لسبب تأديبى سنتان على الأقل .
(و) ألا يكون من أعضاء مجلسى الشعب أو الشورى أو المجلس الشعبية المحلية أو متفرغا للعمل السياسى وذلك طوال مدة العضوية أو التفرغ ما لم يكن مشتغلا أصلا بهذا العمل قبل عضويته أو تفرغه .
(ز) ألا يكون من الأقارب من الدرجة الأولى لأحد شاغلى المناصب السياسية أو لأحد من الفئات المنصوص عليها فى البند السابق .
(ح) ألا يكون من الأقارب من الدرجة الأولى لأحد العاملين من درجة مدير عام فما فوقها ومن فى مستواهم من أعضاء لجان المشتريات أو البيع أو البت فى إحدى الجهات المشار إليها بالبند(هـ) .
(ط) ألا يكون طالب القيد مدرجا علي أي من القوائم السلبية .
ثانيا : بالنسبة إلى قيد الشركات :
(أ) أن يكون مركز الشركة الرئيس فى مصر .
(ب) أن يكون من أغراضها القيام بأعمال الوكالة أو الوساطة التجارية أو السمسرة العقارية طبقا لنظامها الأساسى أو عقد تأسيسها .
(ج) أن يكون رأس المال مملوكا بالكامل لشركاء مصريين ، مع مراعاة مضى عشر سنوات على الأقل فى حالة اكتساب الجنسية المصرية بطريق التجنس .
فإذا كان الشريك شخصا اعتبارا فيجب أن يكون مصرى الجنسية ومملوك أغلب رأس ماله لمصريين أصلاء أو مضى على تجنسهم بالجنسية المصرية عشر سنوات على الأقل .
(د) أن يكون جميع الشركاء المتضامنين ، أو جميع المديرين ، أو أعضاء مجلس إدارة شركات المساهمة بحسب الأول ممن تتوفر فى شأنهم الشروط المنصوص عليها فى (أولا) من هذه المادة .
(هـ) ألا يقل رأس مال شركة الأشخاص عن 20000 (عشرين ألف جنيه) ويثبت ذلك من واقع آخر ميزانية قدمتها الشركة إلى مصلحة الضرائب عن السنة المالية السابقة ، أو بتقديم شهادة تفيد إيداع هذا المبلغ فى أحد البنوك المعتمدة فى حالة بدء نشاط الشركة .
وتعفى من الشرطين (ج) و(د) شركات القطاع العام متى كان الاستيراد متصلا بنشاطها ، وتعامل الشركات ذات المسئولية المحدودة معاملة شركات الأشخاص فى تطبيق أحكام هذا القانون .$m244$,'749d6e7932f8f4950a42504007efa50f'),
(3,1,$m244$المادة 3 مكرراً$m244$,$m244$يشترط فيمن يقيد أو يجدد قيده في سجل السماسرة العقاريين المشار إليه في المادة (2) من هذا القانون ، أن تتوافر فيه الشروط الآتية :
أولا - بالنسبة إلي قيد الأشخاص الطبيعيين :
(أ) استيفاء الشروط المتطلبة بالبند أولا من المادة (3) من هذا القانون .
(ب) اجتياز طالب القيد دورة تدريبية متخصصة في مجال السمسرة العقارية قبل القيد بالسجل تتضمن قواعد قراءة الخرائط والمخططات وفقا للقواعد التي يصدر بها قرار من الوزير المختص .
(ج) استيفاء أية شروط أخري متطلبة لفئات معينة من مزاولي مهنة السمسرة العقارية ، على النحو الذي يصدر بتحديده قرار من الوزير المختص .
ثانيا - بالنسبة إلي قيد الأشخاص الاعتباريين :
(أ) أن يكون مركز الشركة الرئيس في مصر ، ويجوز استثناء من ذلك وبقرار من الوزير المختص ، ووفقا للضوابط التي يحددها ، قيد الشركات التي لها مقر في جمهورية مصر العربية .
(ب) أن يكون من أغراض الشركة القيام بأعمال السمسرة العقارية طبقا لنظامها الأساسي أو عقد تأسيسها .
(ج) ألا يقل رأسمال الشركة المدفوع في تاريخ تقديم طلب القيد بالسجل عن عشرين ألف جنيه .
(د) أن يكون جميع الشركاء المتضامنين ، أو المديرين ، أو أعضاء مجلس إدارة شركات المساهمة ، أو القائمين بالإدارة الفعلية ، بحسب الأحوال ، ممن تتوفر في شأنهم الشروط المنصوص عليها في البند أولا من هذه المادة ، ويستثني من شرط الجنسية الشركات التي يكون ضمن مؤسسيها أجانب بقرار من الوزير المختص .
(هـ) استيفاء أية شروط أخري متطلبة لقيد فئات معينة من مزاولي مهنة السمسرة العقارية ، علي النحو الذي يصدر بتحديده قرار من الوزير المختص .$m244$,'731246a1385d4c6bfb1afce4100b3db8'),
(4,0,$m244$المادة 4$m244$,$m244$يشترط لقبول طلب القيد فى سجل الوكلاء والوسطاء التجاريون أو السماسرة العقاريين ما يأتى :
(أ) تقديم عقد الوكالة أو الوساطة التجارية أو السمسرة العقارية بحسب الأحوال ، على أن يتضمن العقد طبيعة عمل الوكيل أو الوسيط التجاري أو السمسار العقاري ، ومسئولة أطراف العقد ، ونسب العمولة المقررة ، وشروط تقاضيها ، وعلى الأخص نوع العملة التى تدفع بها .
(ب) وبالنسبة للشركات أو الجهات الأجنبية مصدرة التوكيل يتعين فضلا عن الشروط السابقة أن يكون العقد موثقا بالغرفة التجارية المختصة أو الجهة الرسمية التى تقوم مقامها ومصدقا عليه من القنصلية المصرية المختصة ، وأن يتضمن التزام الشركة أو الجهة الأجنبية بموافاة هذه القنصلية بكل اتفاق يتضمن تعديلا فى أى بيان من بيانات العقد .
(ج) أن يكون للشركة أو الجهة الأجنبية وكيل تجارى من شركات القطاع العام ما لم ينته هذا التوكيل .$m244$,'0e3ba64fc1346575b78143d661a754cc'),
(5,0,$m244$المادة 5$m244$,$m244$تحدد اللائحة التنفيذية ما يلي :
(أ) الإجراءات والمستندات الخاصة بالقيد والتجديد والتعديل فى بيانات سجل الوكلاء والوسطاء التجاريون أو السماسرة العقاريين .
(ب) المبالغ التى تؤدى عن القيد والتجديد والتعديل واستخراج الصور من السجلات بما لا يجاوز ما يأتى :
جنيه
1000 تأمين يقدم مع طلب القيد .
500 رسم القيد لأول مرة .
200 رسم تجديد القيد .
20 رسم تعديل بيانات القيد .
10 عن الصورة المستخرجة .
ولا يستحق عند الإخطار بحصول الوكيل أو الوسيط التجاري أو السمسار العقاري على توكيل آخر خلاف للقيد بالسجل إلا الرسم المقرر على تعديل بيانات القيد .
كما يستحق رسم واحد عند تجديد القيد ولو تضمن القيد أكثر من توكيل .
ولا يؤدى الوسيط التجاري أو السمسار العقاري متى كان مرتبطا مع المنتج أو التاجر أو الموزع بعقد عمل إلا نصف المبالغ التى تتقرر بالتطبيق لأحكام هذه المادة .$m244$,'2ea9ba0b21f1d9adb737836d118dc3b0'),
(6,0,$m244$المادة 6$m244$,$m244$يحدد القيد كل خمس سنوات من تاريخ القيد أو من تاريخ آخر تجديد ، على أن يقدم الطلب خلال التسعين يوما السابقة لانتهاء المدة ، ومع ذلك يقبل الطلب إذا قدم خلال التسعين يوما التالية لانتهاء المدة ، إذا قام الطالب بسداد الرسم فى هذه الحالة مضاعفا .
ويشطب قيد الوكيل أو الوسيط التجاري أو السمسار العقاري فى حالة عدم تقديم طلب التجديد خلال التسعين يوما المشار إليها .$m244$,'95dc4ecbfeb8b888bd71eb8bd264f8dd'),
(7,0,$m244$المادة 7$m244$,$m244$لا يجوز للشركات أو المنشآت الأجنبية إنشاء مكاتب خدمات علمية أو فنية أو استشارية أو غيرها إلا إذا كان لهذه الشركات أو المنشآت وكيل تجارى فى مصر طبقا لأحكام هذا القانون .
ولا يجوز لهذه الشركات والمنشآت أو مكاتبها المشار إليها بالفقرة السابقة ممارسة أى عمل من أعمال الوكالة أو الوساطة التجارية أو السمسرة العقارية إلا من خلال وكيل أو الوسيط التجاري أو السمسار العقاري مقيد بالسجل المنصوص عليه فى المادة (2) .$m244$,'97396d5275fefa19c6030a4db6972bce'),
(8,0,$m244$المادة 8$m244$,$m244$يشترط لإنشاء المكاتب المشار إليها فى المادة السابقة الحصول على موافقة الوزارة المختصة التى تعد سجلا خاصا تقيد به هذه المكاتب .
وتحدد اللائحة التنفيذية لهذا القانون المبالغ التى تؤدى عن القيد والتجديد وتعديل البيانات فى هذا السجل والعملة التى تدفع بها هذه المبالغ بما لا يجاوز ما يأتى :
جنيه
1000 تأمين يقدم مع طلب القيد .
500 رسم القيد .
200 رسم تجديد القيد .
20 رسم تعديل بيانات القيد$m244$,'d84700c9934ffcf094e3dea962b4c06f'),
(9,0,$m244$المادة 9$m244$,$m244$يسرى على جميع الأشخاص الطبيعيين والاعتباريين والمنشآت من المنتجين أو التجار أو الموزعين ، فى تعاملهم مع الوكلاء التجاريين ، والوسطاء التجاريون أو السماسرة العقاريين ، الأحكام المنظمة لقواعد الخصم لحساب الضريبة وتوريدها والعقوبات المترتبة على مخالفة هذه الأحكام والمنصوص عليها فى قانون الضرائب على الدخل الصادر بالقانون رقم 157 لسنة 1981 ، وذلك بالنسبة لجميع المبالغ التى يدفعونها للوكلاء التجاريين أو الوسطاء التجاريون أو السماسرة العقاريين ، سواء على سبيل العمولة أو السمسرة أو المكافأة أو تحت أى مسمى آخر .
وتنظم اللائحة التنفيذية للقانون إجراءات الإخطار ومواعيد وإجراءات توريد المبالغ المخصومة تحت حساب الضريبة .
فإذا لم يتم خصم النسبة المشار إليها بالفقرة الأولى من هذه المادة التزمت الجهة التى لم تقم بذلك بأدائها إلى مصلحة الضرائب دون الإخلال بحق هذه الجهة فى الرجوع بها على الملتزم بالضريبة .
وإذا لم يتم الإخطار المنصوص عليه بالفقرة الأولى من هذه المادة التزم من أدى هذه المبالغ بأداء الضرائب والغرامات والتعويضات المستحقة عنها على وجه التضامن مع الوكيل أو الوسيط التجاري أو السمسار العقاري .$m244$,'c4e270760cca38589f3778d30e441448'),
(10,0,$m244$المادة 10$m244$,$m244$يتعين على الوكيل التجارى أن يقوم بموافاة الإدارة المختصة بسجل الوكلاء والوسطاء التجاريون أو السماسرة العقاريين بكل تعديل فى البيانات الخاصة بالتوكيل أو التوكيلات التجارية المسندة إليه وعلى الأخص بأى تعديل أو اتفاق منفصل خاص بنسبة العمولة أو مقدارها وذلك خلال ثلاثين يوما على الأكثر من تاريخ حصول التعديل .
فإذا حصل الوكيل التجارى على توكيل آخر خلاف المقيد تعين قيد التوكيل الجديد بالسجل المشار إليه بالمادة (2) قبل ممارسة العمل استنادا إلى هذا التوكيل .$m244$,'81827c2f2c4c4e497c0dbf9948561c75'),
(10,1,$m244$المادة 10 مكرراً$m244$,$m244$يلتزم السمسار العقاري بموافاة الإدارة المختصة بسجل السمسرة العقارية بكل تعديل أو تغيير يطرأ علي البيانات المشار إليها بالمادة (2 مكررا) من هذا القانون ، وذلك خلال ثلاثين يوما علي الأكثر من تاريخ حصول التعديل أو التغيير .$m244$,'a55ee007791627cacd271fe76b28dbf3'),
(11,0,$m244$المادة 11$m244$,$m244$يلتزم الوكيل التجارى بإمساك دفاتر منتظمة تتضمن بيانات صحيحة ، ويتعين أن يقيد بها العمولات التى تستحق له والبنوك المودعة بها .
كما يلتزم بإخطار الإدارة المختصة بسجل الوكلاء والوسطاء التجاريون أو السماسرة العقاريين عند التوقف عن ممارسة نشاط الوكالة التجارية خلال ثلاثين يوما من تاريخ التوقف .
وفى هذه الحالة يرد له مبلغ التأمين .$m244$,'8a95cf1da87dcc92c64150464519f695'),
(11,1,$m244$المادة 11 مكرراً$m244$,$m244$يلتزم السمسار العقاري بإمساك سجل تقيد فيه عمليات السمسرة العقارية التي أجراها ، والعمولات والمبالغ التي تقاضاها ، وثمن المعاملة ، وتاريخ إجرائها ، والبيانات الشخصية للمتعاقدين ، والعربون الذي دفع لإتمامها ، أو غيرها من المعلومات أو البيانات التي يصدر بتحديدها قرار من الوزير المختص .
ويلتزم السمسار العقاري بتقديم السجل المشار إليه بالفقرة الأولي من هذه المادة ، ونسخ من الوثائق والمعلومات والعقود التي يحتفظ بها ، أو أي تعديل أو تغيير يطرأ عليها للوزارة المختصة ، كما يلتزم بتقديم نسخ من الوثائق والمعلومات والعقود للمتعاقدين ، كلما تعلق الأمر بمعاملاتهم .$m244$,'cb6ac36dc7f62d3bccff07902210836b'),
(12,0,$m244$المادة 12$m244$,$m244$يتعين على من يقوم بأى عمل من أعمال الوساطة التجارية أو السمسرة العقارية أن يقوم بإخطار مصلحة الضرائب بكل المبالغ التى تم الوفاء بها مقابل ذلك خلال ثلاثين يوما من تاريخ الوفاء .$m244$,'e7643b29938d0397fa29beb115fec641'),
(12,1,$m244$المادة 12 مكرراً$m244$,$m244$يكون عقد السمسرة العقارية مكتوبا وموضحا فيه البيانات اللازمة ، وعلي وجه الخصوص تاريخ تحريره ، واسم السمسار العقاري ، والعميل ، والرقم القومي لهما ، وبيانات السمسار العقاري من واقع السجل التجاري ، ورقمه الضريبي ، ومواصفات العقار أو الوحدة أو الأرض ، أو غيرها من البيانات التي يصدر بتحديدها قرار من الوزير المختص .
ويتضمن العقد حدود عمل السمسار العقاري والصلاحيات اللازمة للتأكد من بيانات العقار أو الوحدة أو الأرض محل السمسرة العقارية لدي الجهات الحكومية وغير الحكومية في حدود الوكالة الرسمية التي تصدر له من طرفي عقد السمسرة العقارية أو أحدهما .
كما يثبت السمسار العقاري بعقد السمسرة العقارية وسيلة الدفع بصورة كاملة تشمل تحديد نوعها ، ووسيلتها ، وتاريخها ، ومبلغها .$m244$,'d725fb92b94cc0a16259ba75c9801847'),
(12,2,$m244$المادة 12 مكرراً (أ)$m244$,$m244$يلتزم السمسار العقاري بالتحقق من بيانات العقار أو الوحدة أو الأرض ، ويتأكد من المعلومات المقدمة من ذوي الشأن ، ويطابقها مع المعلومات الفعلية المسجلة لدي الجهات الإدارية سواء من حيث المساحة أو الوصف الصحيح .
كما يلتزم السمسار العقاري بالحفاظ علي سرية المعلومات التي يتصل علمه بها ، بموجب الفقرة الأولي من هذه المادة ، وألا يفصح عنها إلا في الحالات التي يسمح فيها القانون بذلك .$m244$,'f129c03ba0931f23699499e08d2afef3'),
(12,3,$m244$المادة 12 مكرراً (ب)$m244$,$m244$تحصل العمولة المتفق عليها في عقد السمسرة العقارية أو أية مبالغ يتقاضاها السمسار العقاري بوسائل الدفع غير النقدي الواردة بقانون تنظيم استخدام وسائل الدفع غير النقدي الصادر بالقانون رقم 18 لسنة 2019 واستثناء من قانون تنظيم استخدام وسائل الدفع غير النقدي المشار إليه يحظر دفع أي مبلغ من المبالغ المذكورة بصورة نقدية يتجاوز عشرة آلاف جنيه .$m244$,'e92a1c15e5adfd2631d8cdc950791e05'),
(13,0,$m244$المادة 13$m244$,$m244$على وزارات الحكومة ومصالحها ووحدات الحكم المحلى والهيئات العامة وشركات ووحدات القطاع العام إذا تكشف لها خلال ممارسة اختصاصها أو نشاطها قيام وكالة تجارية أو توفر عمل من أعمال الوساطة التجارية أو السمسرة العقارية ، أن توافى مصلحة الضرائب بذلك خلال ثلاثين يوما ، مع بيان شخص الوكيل أو الوسيط التجاري أو السمسار العقاري ، والعمل الذي قام به ، والمبالغ التى يكون قد تقاضاها وعلى العموم بكافة ما يتوافر لها من بيانات فى هذا الشأن .$m244$,'aaf107d04ce48f7a5cc97234b3d6eb4c'),
(14,0,$m244$المادة 14$m244$,$m244$على وزارات الحكومة ومصالحها ووحدات الحكم المحلى والهيئات العامة وشركات ووحدات القطاع العام أن تراعى فيما تضعه من شروط لتعاقداتها أن ينص فى العطاء على مقدار العمولة أو السمسرة المقررة دفعها للوكيل التجارى أو أحد وسطاء التجارة أو سماسرة العقارات فى حالة رسو العطاء ، وشخص أو أشخاص من يتقاضونها ، مع وجوب إيداع هذه المبالغ لحساب أصحاب الحق فيها فى أحد البنوك العامة بجمهورية مصر العربية والخاضعة لإشراف البنك المركزى وبالعملة المتفق عليها بين الأطراف .
ويجوز للجهات المشار إليها بالفقرة الأولى من هذه المادة أن تنص على إنقاص العطاء أو زيادته ، حسب الأحوال ، بمقدار العمولة أو مقابل الوساطة على أن تؤدى هذه الجهات إلى الوكيل أو الوسيط التجاري أو السمسار العقاري العمولة أو مقابل الوساطة بالقدر ووفق الشروط التى يتفق عليها .$m244$,'1f732ed6d77fbcc1b7ab19e38635bc1d'),
(15,0,$m244$المادة 15$m244$,$m244$يجب أن تتضمن العقود المبرمة بين جهة من الجهات المشار إليها بالفقرة الأولى من المادة السابقة وبين أية جهة أجنبية النص على التزام هذه الجهة الأجنبية بإخطار الجهة المتعاقدة بكل المبالغ التى تستحق عليها بمناسبة هذا التعاقد ، أيا كان مسمى هذا المبلغ ، لوكيل تجارى أو أحد وسطاء التجارة أو سماسرة العقارات أو أى شخص آخر أيا كانت صفته ، وسواء كان الاستحقاق سابقا على إبرام العقد أو مرتبطا به أو لاحقا عليه ، وعلى أنه إذا لم تقم الجهة الأجنبية بهذا الإخطار ، التزم بأداء الضرائب والغرامات والتعويضات المستحقة عنها على وجه التضامن مع من قبض هذه المبالغ .$m244$,'bf8fb1765e8c3a081fff486d49063635'),
(16,0,$m244$المادة 16$m244$,$m244$مع عدم الإخلال بأية عقوبة أشد ينص عليها قانون آخر ، يعاقب بالحبس مدة لا تزيد علي سنتين وبغرامة لا تقل عن خمسين ألف جنيه ولا تجاوز مليون جنيه أو بإحدي هاتين العقوبتين ، كل من مارس مهنة الوكالة التجارية أو قام بعمل من أعمال الوساطة التجارية أو السمسرة العقارية أو أنشأ أو أدار منشأة للقيام بأحد الأغراض المتقدمة ، دون أن يكون مقيدا بأي من السجلين المشار إليهما بالمادة (2) من هذا القانون ، فضلا عن الحكم بحرمان مرتكبها من مزاولة النشاط لمدة لا تجاوز سنتين ، وغلق المنشأة لمدة مساوية لمدة الحرمان من مزاولة النشاط . كما يعاقب بغرامة لا تقل عن ثلاثين ألف جنيه ولا تجاوز خمسين ألف جنيه كل من خالف حكم الفقرة الثانية من المادة (10) من هذا القانون ، ويستتبع الحكم الصادر بالإدانة إلغاء القيد ، وسقوط الحق في استرداد التأمين .$m244$,'81c35461a19fdeac4544dfc0c52b083e'),
(16,1,$m244$المادة 16 مكرراً$m244$,$m244$يعاقب بغرامة لا تقل عن (2%) من قيمة المبلغ المدفوع نقدا ولا تجاوز نسبة (10%) من قيمة هذا المبلغ ، وبحد أقصي مليون جنيه كل من خالف أحكام المادة (12 مكررا ب) من هذا القانون .$m244$,'65c19dd7f962517b45e06033de3ec04d'),
(16,2,$m244$المادة 16 مكرراً (أ)$m244$,$m244$يعاقب بغرامة لا تقل عن عشرة آلاف جنيه ولا تجاوز خمسين ألف جنيه كل من خالف أحكام المواد أرقام 10 مكررا ، 11 مكررا ، 12 مكررا ، 12 مكررا أ من هذا القانون .$m244$,'b9894d6f9a07c84c503a061f4988e015'),
(17,0,$m244$المادة 17$m244$,$m244$مع عدم الإخلال بأية عقوبة أشد ينص عليها قانون آخر ، يعاقب بذات العقوبة المنصوص عليها بالفقرة الأولي من المادة (16) من هذا القانون ، كل من تم قيده أو تجديد قيده بأي من السجلين المنصوص عليهما في المادة (2) من هذا القانون ، بناء علي بيانات غير صحيحة تعمد ذكرها ، أو بناء حجب بيانات أو معلومات أو سجلات أو مستندات كان من الواجب تقديمها أو الإدلاء بها ، وتعمد حجبها ، وذلك كله فيما يتعلق بتوافر شروط القيد بأي من السجلين المشار إليهما .
ويترتب علي صدور الحكم بالإدانة ، وفقا لحكم الفقرة الأولي من هذه المادة ، الحكم بحرمان المحكوم عليه من مزاولة النشاط مدة لا تجاوز سنتين ، وإلغاء القيد ، وسقوط الحق في استرداد التأمين ، وغلق المنشأة لمدة مساوية لمدة الحرمان من مزاولة النشاط .$m244$,'6c3493f2b06f88d6b46d6b76d6e7a29f'),
(18,0,$m244$المادة 18$m244$,$m244$يعاقب بالحبس مدة لا تزيد علي ستة أشهر وبغرامة لا تزيد علي خمسين ألف جنيه أو بإحدي هاتين العقوبتين ، كل وكيل أو وسيط تجاري أو سمسار عقاري مارس العمل بعد زوال أحد شروط القيد المنصوص عليها في أي من المادتين (3 ، 3 مكررا) من هذا القانون مع علمه بذلك ، فضلا عن الحكم بإلغاء القيد وسقوط الحق في استرداد التأمين .$m244$,'5de5d8eb9e34b17ad167ef5a20349cb2'),
(19,0,$m244$المادة 19$m244$,$m244$في الأحوال التي ترتكب فيها الجريمة بواسطة شخص اعتباري يعاقب المسئول عن الإدارة الفعلية لهذا الشخص الاعتباري بالعقوبات ذاتها المقررة عن الأفعال التي ترتكب بالمخالفة لأحكام هذا القانون ، إذا ثبت علمه بها ، وكانت الجريمة قد وقعت بسبب إخلاله بواجبات وظيفته . ويعاقب الشخص الاعتباري بغرامة لا تقل عن خمسين ألف جنيه ولا تجاوز مليون جنيه ، ويكون مسئولا بالتضامن عن الوفاء بما يحكم به من عقوبات مالية إذا كانت الجريمة التي وقعت بالمخالفة لأحكام هذا القانون قد ارتكبت من أحد العاملين به باسمه ولصالحه .$m244$,'20b41b78fccc0fb38cae7d4b56894060'),
(20,0,$m244$المادة 20$m244$,$m244$تنشر الأحكام النهائية الصادرة في الجرائم المنصوص عليها بالمواد أرقام (16 ، 17 ، 18 ، 19) من هذا القانون في جريدتين يوميتين واسعتي الانتشار يحددهما الحكم ، وبالنشرة التي تعدها الوزارة المختصة بسجلي الوكلاء والوسطاء التجاريين أو السماسرة العقاريين ، وذلك علي نفقة المحكوم عليه .$m244$,'bf6eca61c439b2f1722d2c71efaf5e8b'),
(20,1,$m244$المادة 20 مكرراً$m244$,$m244$يجوز للوزير المختص التصالح عن أي من الجرائم المنصوص عليها في هذا القانون قبل إقامة الدعوي الجنائية ، مقابل أداء مبلغ لا يقل عن مثلي الحد الأدني ولا يجاوز الحد الأقصي للغرامة المقررة ، ويجوز التصالح بعد إقامة الدعوي الجنائية وقبل صدور حكم فيها مقابل أداء مبلغ لا يقل عن أربعة أمثال الحد الأدني ولا يجاوز الحد الأقصي للغرامة المقررة ، كما يجوز التصالح بعد صدور الحكم الجنائي مقابل أداء مبلغ لا يقل عن الحد الأقصي للغرامة المقررة ولا يجاوز مثليه ، ويترتب علي التصالح انقضاء الدعوي الجنائية بالنسبة للجريمة التي تم التصالح في شأنها ، وتأمر النيابة العامة بوقف تنفيذ العقوبة إذا حصل التصالح أثناء تنفيذ العقوبة ولو كان ذلك بعد صيرورة الحكم باتا .$m244$,'e0c9cc960b5b35a14325595e55cb000c'),
(21,0,$m244$المادة 21$m244$,$m244$إذا خالف الوكيل التجارى أحكام الفقرة الأولى من المادة (10) من هذا القانون سقط حقه فى التأمين وعليه أن يؤدى تأمينا مضاعفا خلال ثلاثين يوما من تاريخ إخطاره بسقوط حقه فى التأمين بكتاب موصى عليه بعلم الوصول على آخر عنوان له أخطر به الإدارة المختصة بالسجل المشار إليه بالمادة (2) من هذا القانون .
وفى حالة تكرار المخالفة لحكم الفقرة الأولى من المادة (10) من هذا القانون يلغى القيد بقرار من وزير الاقتصاد ويسقط الحق فى استرداد التأمين المضاعف .$m244$,'8a1e2e9aaec69167c804fe4a7f7cf041'),
(22,0,$m244$المادة 22$m244$,$m244$يلغى قيد الوكيل أو الوسيط التجاري أو السمسار العقاري بقرار مسبب يصدره وزير الاقتصاد فى الأحوال الآتية :
(أ) مخالفة أحكام الفقرة الأولى من المادة (10) أو الفقرة الأولى من المادة (11) أو المادة (12) ، من هذا القانون ، ويترتب على إلغاء القيد فى هذه الحالة سقوط الحق فى استرداد التأمين .
(ب) إذا فقد الوكيل أو الوسيط التجاري أو السمسار العقاري شرطا من شروط القيد فى سجل الوكلاء التجاريين .
(ج) فى حالة وفاة الشخص الطبيعى أو انقضاء الشخص الاعتبارى .
(د) مخالفة أحكام المواد (11 مكررا ، 12 مكررا ، 12 مكررا "أ") من هذا القانون .$m244$,'26b469c26ead2dd21b04011049cd0ac1'),
(23,0,$m244$المادة 23$m244$,$m244$لا يجوز لمن صدر ضده حكم فى جريمة من الجرائم المنصوص عليها فى هذا القانون أن يعمل بأية صفة كانت لدى منشأة أو شركة تمارس أعمال الوكالة أو الوساطة التجارية أو السمسرة العقارية كما لا يجوز إعادة قيد من ألغى قيده بسجل الوكلاء والوسطاء التجاريون أو السماسرة العقاريين بالتطبيق لأحكام المادتين 21 ، 22 من هذا القانون إلا بعد مضى خمس سنوات على الأقل من تاريخ إلغاء القيد ، ولا يجوز له خلال هذه المدة أن يعمل بأية صفة كانت بمنشأة أو شركة تمارس أعمال الوكالة أو الوساطة التجارية أو السمسرة العقارية أو أن يشترك فى تأسيس أو إدارة شركة من الشركات التى تمارس أعمال الوكالة أو الوساطة التجارية أو السمسرة العقارية .$m244$,'ca1b34b8fab6407fa3cdf43324a3acd8'),
(24,0,$m244$المادة 24$m244$,$m244$يعاقب تأديبيا العامل المسئول عن مخالفة حكم المادة (13) من هذا القانون .
فإذا ثبت أن المخالفة عمدية وبالتواطؤ مع الوكيل أو الوسيط التجاري أو السمسار العقاري التزم العامل مع الوكيل أو الوسيط التجاري أو السمسار العقاري بالتضامن ، بما يستحق من مبالغ الضريبة والتعويضات والغرامات كل ذلك مع عدم الإخلال بأية عقوبة أشد منصوص عليها بقانون آخر .$m244$,'9a2d97696cda5b788cef1b4c3d846eed'),
(25,0,$m244$المادة 25$m244$,$m244$يتعين على الوكلاء التجاريين وعلى المكاتب المشار إليها بالمادة (7) من هذا القانون القائمين بالعمل عند نفاذ هذا القانون اتخاذ الإجراءات المنصوص عليها للقيد فى السجلات المعدة لذلك خلال المدة التى تحددها اللائحة التنفيذية .$m244$,'b9c67abd373498109066c9eae4d5e687'),
(26,0,$m244$المادة 26$m244$,$m244$يكون للعاملين القائمين على تنفيذ أحكام هذا القانون الذين يصدر بتحديدهم قرار من وزير العدل بعد الاتفاق مع الوزير المختص صفة مأمورى الضبط القضائى للكشف عن المخالفات التى تقع لأحكامه أو لأحكام اللائحة التنفيذية له .$m244$,'966de84a2d485818956c15a2b845f11d'),
(27,0,$m244$المادة 27$m244$,$m244$تراعى سرية البيانات التى يتضمنها سجل الوكلاء والوسطاء التجاريون أو السماسرة العقاريين ولا يجوز لغير القائمين على تنفيذ أحكام هذا القانون الاطلاع عليها ، وعلى كل من اطلع بحكم وظيفته على السجل أو البيانات المتعلقة به أو المكاتبات بين طالبى القيد أو تعديل البيانات أو التجديد وبين الإدارة المختصة بالسجل المشار إليه بالمادة (2) من هذا القانون أو بين هذه الإدارة والوكلاء أو الوسطاء التجاريون أو السماسرة العقاريين ، أن يراعى السرية التى تتوفر لهذه البيانات والمعلومات ويعاقب كل من يخالف ذلك بالعقوبة المنصوص عليها بالمادة 310 من قانون العقوبات .$m244$,'4db92ab667b5bd3a27de294006c8be73'),
(28,0,$m244$المادة 28$m244$,$m244$تصدر اللائحة التنفيذية لهذا القانون بقرار من الوزير المختص ، خلال أربعة أشهر من تاريخ نشره فى الجريدة الرسمية وتتضمن على وجه الخصوص تحديد مدة سريان القيد بحيث لا تقل عن سنة ولا تزيد على خمس سنوات .
كما تتضمن الجزاءات التى تترتب على مخالفة أحكامها بما لا يجاوز عقوبة الغرامة بحد أقصى مائة جنيه كما تحدد الحالات التى يجوز فيها بقرار من الوزير المختص شطب القيد بالسجل المشار إليه فى المادة (2) لمدة لا تجاوز ثلاث سنوات .$m244$,'3771109b9f42e42a6f2a015ed430d977');

INSERT INTO m244_ver VALUES
(0,0,1,$m244$قانون رقم 120 لسنة 1982 بإصدار قانون تنظيم أعمال الوكالة التجارية وبعض أعمال الوساطة التجارية أو السمسرة العقارية
باسم الشعب رئيس الجمهورية قرر مجلس الشعب القانون الآتى نصه ، وقد أصدرناه :$m244$,'690668ad2306e7bbda1f482fbcc64c59',DATE '2022-04-12',NULL,'active',21,2022,$m244$عُدل مسمى القانون بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12) (علامة * فى المصدر)؛ النص هنا هو الحالى كما طُبع بالمصدر. المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(1,-1,1,$m244$يعمل بأحكام القانون المرافق فى شأن تنظيم أعمال الوكالة التجارية وبعض أعمال الوساطة التجارية أو السمسرة العقارية .$m244$,'fde3e671dbdde78d39bd1befa6ed131b',DATE '2022-04-12',NULL,'active',21,2022,$m244$عُدل مسمى القانون بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12) (علامة * فى المصدر)؛ النص هنا هو الحالى كما طُبع بالمصدر. المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(2,-1,1,$m244$تلغى القوانين أرقام 107 لسنة 1961 ببعض الأحكام الخاصة بتنظيم أعمال الوكالة التجارية و93 لسنة 1974 فى شأن حق المواطنين فى ممارسة تمثيل الشركات الأجنبية و117 لسنة 1975 فى شأن رسوم القيد فى سجلات أعمال الوكالة التجارية ، كما يلغى كل حكم يخالف أحكام القانون المرافق .$m244$,'ddda561cbecf88e95db5c687caa99b71',DATE '1983-05-05',NULL,'active',NULL,NULL,$m244$لا علامة تعديل على هذه المادة بالمصدر؛ تاريخ العمل بالأصل (1983-05-05) تقريبى: تسعة أشهر بعد نشر القانون بالجريدة الرسمية العدد 31 (تابع) فى 5 أغسطس 1982 بحسب مصدر ثانوى لا يتضمنه الملف المرفوع، ويُراجع بشرياً قبل الاستناد إليه.$m244$),
(3,-1,1,$m244$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به بعد تسعة أشهر من تاريخ نشره .
يبصم هذا القانون بخاتم الدولة ، وينفذ كقانون من قوانينها ،
صدر برئاسة الجمهورية فى 6 شوال سنة 1402 (26 يوليه سنة 1982)$m244$,'2c7cf707bf66cbe90cb56421a9317950',DATE '1983-05-05',NULL,'active',NULL,NULL,$m244$لا علامة تعديل على هذه المادة بالمصدر؛ تاريخ العمل بالأصل (1983-05-05) تقريبى: تسعة أشهر بعد نشر القانون بالجريدة الرسمية العدد 31 (تابع) فى 5 أغسطس 1982 بحسب مصدر ثانوى لا يتضمنه الملف المرفوع، ويُراجع بشرياً قبل الاستناد إليه.$m244$),
(1,0,1,$m244$في تطبيق أحكام هذا القانون ، يقصد بالعبارات والكلمات الآتية المعاني المبينة قرين كل منها :
الوكيل التجاري : كل شخص طبيعي أو اعتباري يقوم بصفة معتادة ، دون أن يكون مرتبطا بعقد عمل أو عقد تأجير خدمات ، بتقديم العطاءات أو بإبرام عمليات الشراء أو البيع أو التأجير أو تقديم الخدمات باسم ولحساب المنتجين أو التجار أو الموزعين أو باسمه ولحساب أحد هؤلاء .
الوسيط التجاري : كل شخص طبيعي أو اعتباري اقتصر نشاطه ، ولو عن صفقة واحدة على البحث عن متعاقد أو التفاوض معه لإقناعه بالتعاقد ، وكذلك كل من قام بأي عمل من أعمال الوكالة التجارية ولو على غير اعتياد ولمرة واحدة ، أو كان مرتبطا مع المنتج أو التاجر أو الموزع بعقد عمل .
السمسار العقاري : كل من قيد بالسجل المنشأ لهذا الغرض ، ويقوم بأعمال السمسرة أو السعي لإبرام العقود المتعلقة بالعقارات والأراضي المبنية أو الفضاء ، سواء أعمال شرائها أو بيعها أو تأجيرها أو التوسط في شيء مما تقدم .
القوائم السلبية : قوائم الكيانات الإرهابية والإرهابيين المنظمة بموجب القانون رقم 8 لسنة 2015 في شأن تنظيم قوائم الكيانات الإرهابية والإرهابيين ، والأسماء والكيانات المدرجة بقاعدة البيانات لدي وحدة مكافحة غسل الأموال المنشأة بموجب قانون مكافحة غسل الأموال الصادر بالقانون رقم 80 لسنة 2002
الوزارة المختصة : الوزارة المعنية بشئون التجارة الخارجية .
الوزير المختص : الوزير المعني بشئون التجارة الخارجية .$m244$,'a62610fe85aac928dd303616032a812d',DATE '2022-04-12',NULL,'active',21,2022,$m244$استُبدل نص هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12). المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(2,0,1,$m244$مع عدم الإخلال بأحكام القانون رقم 34 لسنة 1976 في شأن السجل التجاري ، تحظر مزاولة أي عمل من أعمال الوكالة التجارية أو الوساطة التجارية أو السمسرة العقارية ، إلا لمن يكون اسمه مقيدا في سجل الوكلاء والوسطاء التجاريين أو السماسرة العقاريين ، بحسب الأحوال ، المعدين لذلك الغرض بالوزارة المختصة .$m244$,'c029b51c6e79facd18d50b036464ec31',DATE '2022-04-12',NULL,'active',21,2022,$m244$استُبدل نص هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12). المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(2,1,1,$m244$ينشأ بالوزارة المختصة سجل إلكتروني لقيد السماسرة العقاريين يسمي "سجل السمسرة العقارية" تدون فيه بيانات ومعلومات المقيدين بسجل مزاولة مهنة السمسرة العقارية ، بما فيها بياناتهم الشخصية الأساسية ، وبيانات محل مزاولتهم المهنة ، والكود الذي حصل عليه والفئة التي ينتمي إليها ، وغيرها من البيانات ، والمعلومات ، والإحصائيات اللازمة لتنظيم نشاط السمسرة العقارية .
وتجري الوزارة المختصة تحديثا للسجل المشار إليه بالفقرة الأولي من هذه المادة بشكل مستمر ومنتظم ، بما يتفق مع المستجدات في هذا النشاط ، وتنشر القائمة المحدثة للسماسرة العقاريين على مستوي الجمهورية على الموقع الإلكتروني لها بما يتيح للجميع الاطلاع عليها .
ولذوي الشأن الحصول على صورة مصدقة من المعلومات المقيدة في السجل المشار إليه بالفقرة الأولي من هذه المادة أو شهادة سلبية بعدم إدراج أمر معين فيه .
ويصدر الوزير المختص القرارات اللازمة لتنفيذ أحكام هذه المادة ، وتحديد فئات وأنواع السماسرة العقاريين الذين يدرجون بسجل السماسرة العقاريين .$m244$,'a0ec3df92b7a0d353b7c0b303bfe9fec',DATE '2022-04-12',NULL,'active',21,2022,$m244$مادة مضافة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12). المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا توجد نسخة سابقة لأن المادة جديدة.$m244$),
(3,0,1,$m244$يشترط فيمن يقيد أو يجدد قيده في سجل الوكلاء والوسطاء التجاريين المشار إليه في المادة (2) من هذا القانون ، الشروط الآتية :
أولا : بالنسبة إلى قيد الأشخاص الطبيعيين :
(أ) أن يكون مصرى الجنسية . وبالنسبة لمن تجنس بالجنسية المصرية يجب أن يكون قد مضى على اكتسابه هذه الجنسية عشر سنوات على الأقل .
(ب) أن يكون كامل الأهلية .
(ج) أن يكون حسن السمعة ، ولم يسبق الحكم عليه بعقوبة جناية أو بعقوبة مقيدة للحرية فى جريمة مخلة بالشرف أو الأمانة ، أو فى إحدى الجرائم المنصوص عليها فى هذا القانون أو قوانين الاستيراد ، أو التصدير ، أو النقد ، أو الجمارك ، أو الضرائب ، أو التموين ، أو الشركات ، أو التجارة ، ما لم يكن قد رد إليه اعتباره .
(د) ألا يكون قد أشهر إفلاسه ، ما لم يكن قد رد إليه اعتباره .
(هـ) ألا يكون من العاملين بالحكومة ووحدات الحكم المحلى والهيئات العامة وشركات ووحدات القطاع العام . ويشترط بالنسبة للعاملين السابقين فى هذه الجهات أن يكون قد مضى على تاريخ ترك الخدمة بالاستقالة أو لسبب تأديبى سنتان على الأقل .
(و) ألا يكون من أعضاء مجلسى الشعب أو الشورى أو المجلس الشعبية المحلية أو متفرغا للعمل السياسى وذلك طوال مدة العضوية أو التفرغ ما لم يكن مشتغلا أصلا بهذا العمل قبل عضويته أو تفرغه .
(ز) ألا يكون من الأقارب من الدرجة الأولى لأحد شاغلى المناصب السياسية أو لأحد من الفئات المنصوص عليها فى البند السابق .
(ح) ألا يكون من الأقارب من الدرجة الأولى لأحد العاملين من درجة مدير عام فما فوقها ومن فى مستواهم من أعضاء لجان المشتريات أو البيع أو البت فى إحدى الجهات المشار إليها بالبند(هـ) .
(ط) ألا يكون طالب القيد مدرجا علي أي من القوائم السلبية .
ثانيا : بالنسبة إلى قيد الشركات :
(أ) أن يكون مركز الشركة الرئيس فى مصر .
(ب) أن يكون من أغراضها القيام بأعمال الوكالة أو الوساطة التجارية أو السمسرة العقارية طبقا لنظامها الأساسى أو عقد تأسيسها .
(ج) أن يكون رأس المال مملوكا بالكامل لشركاء مصريين ، مع مراعاة مضى عشر سنوات على الأقل فى حالة اكتساب الجنسية المصرية بطريق التجنس .
فإذا كان الشريك شخصا اعتبارا فيجب أن يكون مصرى الجنسية ومملوك أغلب رأس ماله لمصريين أصلاء أو مضى على تجنسهم بالجنسية المصرية عشر سنوات على الأقل .
(د) أن يكون جميع الشركاء المتضامنين ، أو جميع المديرين ، أو أعضاء مجلس إدارة شركات المساهمة بحسب الأول ممن تتوفر فى شأنهم الشروط المنصوص عليها فى (أولا) من هذه المادة .
(هـ) ألا يقل رأس مال شركة الأشخاص عن 20000 (عشرين ألف جنيه) ويثبت ذلك من واقع آخر ميزانية قدمتها الشركة إلى مصلحة الضرائب عن السنة المالية السابقة ، أو بتقديم شهادة تفيد إيداع هذا المبلغ فى أحد البنوك المعتمدة فى حالة بدء نشاط الشركة .
وتعفى من الشرطين (ج) و(د) شركات القطاع العام متى كان الاستيراد متصلا بنشاطها ، وتعامل الشركات ذات المسئولية المحدودة معاملة شركات الأشخاص فى تطبيق أحكام هذا القانون .$m244$,'749d6e7932f8f4950a42504007efa50f',DATE '2022-04-12',NULL,'active',21,2022,$m244$استُبدلت الفقرة الأولى من المادة وأُضيف البند (ط) من «أولاً» وعُدلت مسميات فى البند (ب) من «ثانياً» بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12). المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(3,1,1,$m244$يشترط فيمن يقيد أو يجدد قيده في سجل السماسرة العقاريين المشار إليه في المادة (2) من هذا القانون ، أن تتوافر فيه الشروط الآتية :
أولا - بالنسبة إلي قيد الأشخاص الطبيعيين :
(أ) استيفاء الشروط المتطلبة بالبند أولا من المادة (3) من هذا القانون .
(ب) اجتياز طالب القيد دورة تدريبية متخصصة في مجال السمسرة العقارية قبل القيد بالسجل تتضمن قواعد قراءة الخرائط والمخططات وفقا للقواعد التي يصدر بها قرار من الوزير المختص .
(ج) استيفاء أية شروط أخري متطلبة لفئات معينة من مزاولي مهنة السمسرة العقارية ، على النحو الذي يصدر بتحديده قرار من الوزير المختص .
ثانيا - بالنسبة إلي قيد الأشخاص الاعتباريين :
(أ) أن يكون مركز الشركة الرئيس في مصر ، ويجوز استثناء من ذلك وبقرار من الوزير المختص ، ووفقا للضوابط التي يحددها ، قيد الشركات التي لها مقر في جمهورية مصر العربية .
(ب) أن يكون من أغراض الشركة القيام بأعمال السمسرة العقارية طبقا لنظامها الأساسي أو عقد تأسيسها .
(ج) ألا يقل رأسمال الشركة المدفوع في تاريخ تقديم طلب القيد بالسجل عن عشرين ألف جنيه .
(د) أن يكون جميع الشركاء المتضامنين ، أو المديرين ، أو أعضاء مجلس إدارة شركات المساهمة ، أو القائمين بالإدارة الفعلية ، بحسب الأحوال ، ممن تتوفر في شأنهم الشروط المنصوص عليها في البند أولا من هذه المادة ، ويستثني من شرط الجنسية الشركات التي يكون ضمن مؤسسيها أجانب بقرار من الوزير المختص .
(هـ) استيفاء أية شروط أخري متطلبة لقيد فئات معينة من مزاولي مهنة السمسرة العقارية ، علي النحو الذي يصدر بتحديده قرار من الوزير المختص .$m244$,'731246a1385d4c6bfb1afce4100b3db8',DATE '2022-04-12',NULL,'active',21,2022,$m244$مادة مضافة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12). المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا توجد نسخة سابقة لأن المادة جديدة.$m244$),
(4,0,1,$m244$يشترط لقبول طلب القيد فى سجل الوكلاء والوسطاء التجاريون أو السماسرة العقاريين ما يأتى :
(أ) تقديم عقد الوكالة أو الوساطة التجارية أو السمسرة العقارية بحسب الأحوال ، على أن يتضمن العقد طبيعة عمل الوكيل أو الوسيط التجاري أو السمسار العقاري ، ومسئولة أطراف العقد ، ونسب العمولة المقررة ، وشروط تقاضيها ، وعلى الأخص نوع العملة التى تدفع بها .
(ب) وبالنسبة للشركات أو الجهات الأجنبية مصدرة التوكيل يتعين فضلا عن الشروط السابقة أن يكون العقد موثقا بالغرفة التجارية المختصة أو الجهة الرسمية التى تقوم مقامها ومصدقا عليه من القنصلية المصرية المختصة ، وأن يتضمن التزام الشركة أو الجهة الأجنبية بموافاة هذه القنصلية بكل اتفاق يتضمن تعديلا فى أى بيان من بيانات العقد .
(ج) أن يكون للشركة أو الجهة الأجنبية وكيل تجارى من شركات القطاع العام ما لم ينته هذا التوكيل .$m244$,'0e3ba64fc1346575b78143d661a754cc',DATE '2022-04-12',NULL,'active',21,2022,$m244$عُدلت مسميات فى هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12) (علامة * فى المصدر: «السمسرة العقارية» و«السمسار العقارى» و«الوزير/الوزارة المختصة» ونحوها)؛ النص هنا هو الحالى كما طُبع بالمصدر، بما فيه صيغ الجمع المرفوعة مثل «التجاريون». المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(5,0,1,$m244$تحدد اللائحة التنفيذية ما يلي :
(أ) الإجراءات والمستندات الخاصة بالقيد والتجديد والتعديل فى بيانات سجل الوكلاء والوسطاء التجاريون أو السماسرة العقاريين .
(ب) المبالغ التى تؤدى عن القيد والتجديد والتعديل واستخراج الصور من السجلات بما لا يجاوز ما يأتى :
جنيه
1000 تأمين يقدم مع طلب القيد .
500 رسم القيد لأول مرة .
200 رسم تجديد القيد .
20 رسم تعديل بيانات القيد .
10 عن الصورة المستخرجة .
ولا يستحق عند الإخطار بحصول الوكيل أو الوسيط التجاري أو السمسار العقاري على توكيل آخر خلاف للقيد بالسجل إلا الرسم المقرر على تعديل بيانات القيد .
كما يستحق رسم واحد عند تجديد القيد ولو تضمن القيد أكثر من توكيل .
ولا يؤدى الوسيط التجاري أو السمسار العقاري متى كان مرتبطا مع المنتج أو التاجر أو الموزع بعقد عمل إلا نصف المبالغ التى تتقرر بالتطبيق لأحكام هذه المادة .$m244$,'2ea9ba0b21f1d9adb737836d118dc3b0',DATE '2022-04-12',NULL,'active',21,2022,$m244$عُدلت مسميات فى هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12) (علامة * فى المصدر: «السمسرة العقارية» و«السمسار العقارى» و«الوزير/الوزارة المختصة» ونحوها)؛ النص هنا هو الحالى كما طُبع بالمصدر، بما فيه صيغ الجمع المرفوعة مثل «التجاريون». المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(6,0,1,$m244$يحدد القيد كل خمس سنوات من تاريخ القيد أو من تاريخ آخر تجديد ، على أن يقدم الطلب خلال التسعين يوما السابقة لانتهاء المدة ، ومع ذلك يقبل الطلب إذا قدم خلال التسعين يوما التالية لانتهاء المدة ، إذا قام الطالب بسداد الرسم فى هذه الحالة مضاعفا .
ويشطب قيد الوكيل أو الوسيط التجاري أو السمسار العقاري فى حالة عدم تقديم طلب التجديد خلال التسعين يوما المشار إليها .$m244$,'95dc4ecbfeb8b888bd71eb8bd264f8dd',DATE '2022-04-12',NULL,'active',21,2022,$m244$عُدلت مسميات فى هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12) (علامة * فى المصدر: «السمسرة العقارية» و«السمسار العقارى» و«الوزير/الوزارة المختصة» ونحوها)؛ النص هنا هو الحالى كما طُبع بالمصدر، بما فيه صيغ الجمع المرفوعة مثل «التجاريون». المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(7,0,1,$m244$لا يجوز للشركات أو المنشآت الأجنبية إنشاء مكاتب خدمات علمية أو فنية أو استشارية أو غيرها إلا إذا كان لهذه الشركات أو المنشآت وكيل تجارى فى مصر طبقا لأحكام هذا القانون .
ولا يجوز لهذه الشركات والمنشآت أو مكاتبها المشار إليها بالفقرة السابقة ممارسة أى عمل من أعمال الوكالة أو الوساطة التجارية أو السمسرة العقارية إلا من خلال وكيل أو الوسيط التجاري أو السمسار العقاري مقيد بالسجل المنصوص عليه فى المادة (2) .$m244$,'97396d5275fefa19c6030a4db6972bce',DATE '2022-04-12',NULL,'active',21,2022,$m244$عُدلت مسميات فى هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12) (علامة * فى المصدر: «السمسرة العقارية» و«السمسار العقارى» و«الوزير/الوزارة المختصة» ونحوها)؛ النص هنا هو الحالى كما طُبع بالمصدر، بما فيه صيغ الجمع المرفوعة مثل «التجاريون». المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(8,0,1,$m244$يشترط لإنشاء المكاتب المشار إليها فى المادة السابقة الحصول على موافقة الوزارة المختصة التى تعد سجلا خاصا تقيد به هذه المكاتب .
وتحدد اللائحة التنفيذية لهذا القانون المبالغ التى تؤدى عن القيد والتجديد وتعديل البيانات فى هذا السجل والعملة التى تدفع بها هذه المبالغ بما لا يجاوز ما يأتى :
