20 رسم تعديل بيانات القيد$m244$,'d84700c9934ffcf094e3dea962b4c06f',DATE '2022-04-12',NULL,'active',21,2022,$m244$عُدلت مسميات فى هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12) (علامة * فى المصدر: «السمسرة العقارية» و«السمسار العقارى» و«الوزير/الوزارة المختصة» ونحوها)؛ النص هنا هو الحالى كما طُبع بالمصدر، بما فيه صيغ الجمع المرفوعة مثل «التجاريون». المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(9,0,1,$m244$يسرى على جميع الأشخاص الطبيعيين والاعتباريين والمنشآت من المنتجين أو التجار أو الموزعين ، فى تعاملهم مع الوكلاء التجاريين ، والوسطاء التجاريون أو السماسرة العقاريين ، الأحكام المنظمة لقواعد الخصم لحساب الضريبة وتوريدها والعقوبات المترتبة على مخالفة هذه الأحكام والمنصوص عليها فى قانون الضرائب على الدخل الصادر بالقانون رقم 157 لسنة 1981 ، وذلك بالنسبة لجميع المبالغ التى يدفعونها للوكلاء التجاريين أو الوسطاء التجاريون أو السماسرة العقاريين ، سواء على سبيل العمولة أو السمسرة أو المكافأة أو تحت أى مسمى آخر .
وتنظم اللائحة التنفيذية للقانون إجراءات الإخطار ومواعيد وإجراءات توريد المبالغ المخصومة تحت حساب الضريبة .
فإذا لم يتم خصم النسبة المشار إليها بالفقرة الأولى من هذه المادة التزمت الجهة التى لم تقم بذلك بأدائها إلى مصلحة الضرائب دون الإخلال بحق هذه الجهة فى الرجوع بها على الملتزم بالضريبة .
وإذا لم يتم الإخطار المنصوص عليه بالفقرة الأولى من هذه المادة التزم من أدى هذه المبالغ بأداء الضرائب والغرامات والتعويضات المستحقة عنها على وجه التضامن مع الوكيل أو الوسيط التجاري أو السمسار العقاري .$m244$,'c4e270760cca38589f3778d30e441448',DATE '2022-04-12',NULL,'active',21,2022,$m244$عُدلت مسميات فى هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12) (علامة * فى المصدر: «السمسرة العقارية» و«السمسار العقارى» و«الوزير/الوزارة المختصة» ونحوها)؛ النص هنا هو الحالى كما طُبع بالمصدر، بما فيه صيغ الجمع المرفوعة مثل «التجاريون». المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(10,0,1,$m244$يتعين على الوكيل التجارى أن يقوم بموافاة الإدارة المختصة بسجل الوكلاء والوسطاء التجاريون أو السماسرة العقاريين بكل تعديل فى البيانات الخاصة بالتوكيل أو التوكيلات التجارية المسندة إليه وعلى الأخص بأى تعديل أو اتفاق منفصل خاص بنسبة العمولة أو مقدارها وذلك خلال ثلاثين يوما على الأكثر من تاريخ حصول التعديل .
فإذا حصل الوكيل التجارى على توكيل آخر خلاف المقيد تعين قيد التوكيل الجديد بالسجل المشار إليه بالمادة (2) قبل ممارسة العمل استنادا إلى هذا التوكيل .$m244$,'81827c2f2c4c4e497c0dbf9948561c75',DATE '2022-04-12',NULL,'active',21,2022,$m244$عُدلت مسميات فى هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12) (علامة * فى المصدر: «السمسرة العقارية» و«السمسار العقارى» و«الوزير/الوزارة المختصة» ونحوها)؛ النص هنا هو الحالى كما طُبع بالمصدر، بما فيه صيغ الجمع المرفوعة مثل «التجاريون». المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(10,1,1,$m244$يلتزم السمسار العقاري بموافاة الإدارة المختصة بسجل السمسرة العقارية بكل تعديل أو تغيير يطرأ علي البيانات المشار إليها بالمادة (2 مكررا) من هذا القانون ، وذلك خلال ثلاثين يوما علي الأكثر من تاريخ حصول التعديل أو التغيير .$m244$,'a55ee007791627cacd271fe76b28dbf3',DATE '2022-04-12',NULL,'active',21,2022,$m244$مادة مضافة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12). المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا توجد نسخة سابقة لأن المادة جديدة.$m244$),
(11,0,1,$m244$يلتزم الوكيل التجارى بإمساك دفاتر منتظمة تتضمن بيانات صحيحة ، ويتعين أن يقيد بها العمولات التى تستحق له والبنوك المودعة بها .
كما يلتزم بإخطار الإدارة المختصة بسجل الوكلاء والوسطاء التجاريون أو السماسرة العقاريين عند التوقف عن ممارسة نشاط الوكالة التجارية خلال ثلاثين يوما من تاريخ التوقف .
وفى هذه الحالة يرد له مبلغ التأمين .$m244$,'8a95cf1da87dcc92c64150464519f695',DATE '2022-04-12',NULL,'active',21,2022,$m244$عُدلت مسميات فى هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12) (علامة * فى المصدر: «السمسرة العقارية» و«السمسار العقارى» و«الوزير/الوزارة المختصة» ونحوها)؛ النص هنا هو الحالى كما طُبع بالمصدر، بما فيه صيغ الجمع المرفوعة مثل «التجاريون». المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(11,1,1,$m244$يلتزم السمسار العقاري بإمساك سجل تقيد فيه عمليات السمسرة العقارية التي أجراها ، والعمولات والمبالغ التي تقاضاها ، وثمن المعاملة ، وتاريخ إجرائها ، والبيانات الشخصية للمتعاقدين ، والعربون الذي دفع لإتمامها ، أو غيرها من المعلومات أو البيانات التي يصدر بتحديدها قرار من الوزير المختص .
ويلتزم السمسار العقاري بتقديم السجل المشار إليه بالفقرة الأولي من هذه المادة ، ونسخ من الوثائق والمعلومات والعقود التي يحتفظ بها ، أو أي تعديل أو تغيير يطرأ عليها للوزارة المختصة ، كما يلتزم بتقديم نسخ من الوثائق والمعلومات والعقود للمتعاقدين ، كلما تعلق الأمر بمعاملاتهم .$m244$,'cb6ac36dc7f62d3bccff07902210836b',DATE '2022-04-12',NULL,'active',21,2022,$m244$مادة مضافة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12). المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا توجد نسخة سابقة لأن المادة جديدة.$m244$),
(12,0,1,$m244$يتعين على من يقوم بأى عمل من أعمال الوساطة التجارية أو السمسرة العقارية أن يقوم بإخطار مصلحة الضرائب بكل المبالغ التى تم الوفاء بها مقابل ذلك خلال ثلاثين يوما من تاريخ الوفاء .$m244$,'e7643b29938d0397fa29beb115fec641',DATE '2022-04-12',NULL,'active',21,2022,$m244$عُدلت مسميات فى هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12) (علامة * فى المصدر: «السمسرة العقارية» و«السمسار العقارى» و«الوزير/الوزارة المختصة» ونحوها)؛ النص هنا هو الحالى كما طُبع بالمصدر، بما فيه صيغ الجمع المرفوعة مثل «التجاريون». المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(12,1,1,$m244$يكون عقد السمسرة العقارية مكتوبا وموضحا فيه البيانات اللازمة ، وعلي وجه الخصوص تاريخ تحريره ، واسم السمسار العقاري ، والعميل ، والرقم القومي لهما ، وبيانات السمسار العقاري من واقع السجل التجاري ، ورقمه الضريبي ، ومواصفات العقار أو الوحدة أو الأرض ، أو غيرها من البيانات التي يصدر بتحديدها قرار من الوزير المختص .
ويتضمن العقد حدود عمل السمسار العقاري والصلاحيات اللازمة للتأكد من بيانات العقار أو الوحدة أو الأرض محل السمسرة العقارية لدي الجهات الحكومية وغير الحكومية في حدود الوكالة الرسمية التي تصدر له من طرفي عقد السمسرة العقارية أو أحدهما .
كما يثبت السمسار العقاري بعقد السمسرة العقارية وسيلة الدفع بصورة كاملة تشمل تحديد نوعها ، ووسيلتها ، وتاريخها ، ومبلغها .$m244$,'d725fb92b94cc0a16259ba75c9801847',DATE '2022-04-12',NULL,'active',21,2022,$m244$مادة مضافة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12). المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا توجد نسخة سابقة لأن المادة جديدة.$m244$),
(12,2,1,$m244$يلتزم السمسار العقاري بالتحقق من بيانات العقار أو الوحدة أو الأرض ، ويتأكد من المعلومات المقدمة من ذوي الشأن ، ويطابقها مع المعلومات الفعلية المسجلة لدي الجهات الإدارية سواء من حيث المساحة أو الوصف الصحيح .
كما يلتزم السمسار العقاري بالحفاظ علي سرية المعلومات التي يتصل علمه بها ، بموجب الفقرة الأولي من هذه المادة ، وألا يفصح عنها إلا في الحالات التي يسمح فيها القانون بذلك .$m244$,'f129c03ba0931f23699499e08d2afef3',DATE '2022-04-12',NULL,'active',21,2022,$m244$مادة مضافة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12). المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا توجد نسخة سابقة لأن المادة جديدة.$m244$),
(12,3,1,$m244$تحصل العمولة المتفق عليها في عقد السمسرة العقارية أو أية مبالغ يتقاضاها السمسار العقاري بوسائل الدفع غير النقدي الواردة بقانون تنظيم استخدام وسائل الدفع غير النقدي الصادر بالقانون رقم 18 لسنة 2019 واستثناء من قانون تنظيم استخدام وسائل الدفع غير النقدي المشار إليه يحظر دفع أي مبلغ من المبالغ المذكورة بصورة نقدية يتجاوز عشرة آلاف جنيه .$m244$,'e92a1c15e5adfd2631d8cdc950791e05',DATE '2022-04-12',NULL,'active',21,2022,$m244$مادة مضافة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12). المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا توجد نسخة سابقة لأن المادة جديدة.$m244$),
(13,0,1,$m244$على وزارات الحكومة ومصالحها ووحدات الحكم المحلى والهيئات العامة وشركات ووحدات القطاع العام إذا تكشف لها خلال ممارسة اختصاصها أو نشاطها قيام وكالة تجارية أو توفر عمل من أعمال الوساطة التجارية أو السمسرة العقارية ، أن توافى مصلحة الضرائب بذلك خلال ثلاثين يوما ، مع بيان شخص الوكيل أو الوسيط التجاري أو السمسار العقاري ، والعمل الذي قام به ، والمبالغ التى يكون قد تقاضاها وعلى العموم بكافة ما يتوافر لها من بيانات فى هذا الشأن .$m244$,'aaf107d04ce48f7a5cc97234b3d6eb4c',DATE '2022-04-12',NULL,'active',21,2022,$m244$عُدلت مسميات فى هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12) (علامة * فى المصدر: «السمسرة العقارية» و«السمسار العقارى» و«الوزير/الوزارة المختصة» ونحوها)؛ النص هنا هو الحالى كما طُبع بالمصدر، بما فيه صيغ الجمع المرفوعة مثل «التجاريون». المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(14,0,1,$m244$على وزارات الحكومة ومصالحها ووحدات الحكم المحلى والهيئات العامة وشركات ووحدات القطاع العام أن تراعى فيما تضعه من شروط لتعاقداتها أن ينص فى العطاء على مقدار العمولة أو السمسرة المقررة دفعها للوكيل التجارى أو أحد وسطاء التجارة أو سماسرة العقارات فى حالة رسو العطاء ، وشخص أو أشخاص من يتقاضونها ، مع وجوب إيداع هذه المبالغ لحساب أصحاب الحق فيها فى أحد البنوك العامة بجمهورية مصر العربية والخاضعة لإشراف البنك المركزى وبالعملة المتفق عليها بين الأطراف .
ويجوز للجهات المشار إليها بالفقرة الأولى من هذه المادة أن تنص على إنقاص العطاء أو زيادته ، حسب الأحوال ، بمقدار العمولة أو مقابل الوساطة على أن تؤدى هذه الجهات إلى الوكيل أو الوسيط التجاري أو السمسار العقاري العمولة أو مقابل الوساطة بالقدر ووفق الشروط التى يتفق عليها .$m244$,'1f732ed6d77fbcc1b7ab19e38635bc1d',DATE '2022-04-12',NULL,'active',21,2022,$m244$عُدلت مسميات فى هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12) (علامة * فى المصدر: «السمسرة العقارية» و«السمسار العقارى» و«الوزير/الوزارة المختصة» ونحوها)؛ النص هنا هو الحالى كما طُبع بالمصدر، بما فيه صيغ الجمع المرفوعة مثل «التجاريون». المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(15,0,1,$m244$يجب أن تتضمن العقود المبرمة بين جهة من الجهات المشار إليها بالفقرة الأولى من المادة السابقة وبين أية جهة أجنبية النص على التزام هذه الجهة الأجنبية بإخطار الجهة المتعاقدة بكل المبالغ التى تستحق عليها بمناسبة هذا التعاقد ، أيا كان مسمى هذا المبلغ ، لوكيل تجارى أو أحد وسطاء التجارة أو سماسرة العقارات أو أى شخص آخر أيا كانت صفته ، وسواء كان الاستحقاق سابقا على إبرام العقد أو مرتبطا به أو لاحقا عليه ، وعلى أنه إذا لم تقم الجهة الأجنبية بهذا الإخطار ، التزم بأداء الضرائب والغرامات والتعويضات المستحقة عنها على وجه التضامن مع من قبض هذه المبالغ .$m244$,'bf8fb1765e8c3a081fff486d49063635',DATE '2022-04-12',NULL,'active',21,2022,$m244$عُدلت مسميات فى هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12) (علامة * فى المصدر: «السمسرة العقارية» و«السمسار العقارى» و«الوزير/الوزارة المختصة» ونحوها)؛ النص هنا هو الحالى كما طُبع بالمصدر، بما فيه صيغ الجمع المرفوعة مثل «التجاريون». المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(16,0,1,$m244$مع عدم الإخلال بأية عقوبة أشد ينص عليها قانون آخر ، يعاقب بالحبس مدة لا تزيد علي سنتين وبغرامة لا تقل عن خمسين ألف جنيه ولا تجاوز مليون جنيه أو بإحدي هاتين العقوبتين ، كل من مارس مهنة الوكالة التجارية أو قام بعمل من أعمال الوساطة التجارية أو السمسرة العقارية أو أنشأ أو أدار منشأة للقيام بأحد الأغراض المتقدمة ، دون أن يكون مقيدا بأي من السجلين المشار إليهما بالمادة (2) من هذا القانون ، فضلا عن الحكم بحرمان مرتكبها من مزاولة النشاط لمدة لا تجاوز سنتين ، وغلق المنشأة لمدة مساوية لمدة الحرمان من مزاولة النشاط . كما يعاقب بغرامة لا تقل عن ثلاثين ألف جنيه ولا تجاوز خمسين ألف جنيه كل من خالف حكم الفقرة الثانية من المادة (10) من هذا القانون ، ويستتبع الحكم الصادر بالإدانة إلغاء القيد ، وسقوط الحق في استرداد التأمين .$m244$,'81c35461a19fdeac4544dfc0c52b083e',DATE '2022-04-12',NULL,'active',21,2022,$m244$استُبدل نص هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12). المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(16,1,1,$m244$يعاقب بغرامة لا تقل عن (2%) من قيمة المبلغ المدفوع نقدا ولا تجاوز نسبة (10%) من قيمة هذا المبلغ ، وبحد أقصي مليون جنيه كل من خالف أحكام المادة (12 مكررا ب) من هذا القانون .$m244$,'65c19dd7f962517b45e06033de3ec04d',DATE '2022-04-12',NULL,'active',21,2022,$m244$مادة مضافة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12). المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا توجد نسخة سابقة لأن المادة جديدة.$m244$),
(16,2,1,$m244$يعاقب بغرامة لا تقل عن عشرة آلاف جنيه ولا تجاوز خمسين ألف جنيه كل من خالف أحكام المواد أرقام 10 مكررا ، 11 مكررا ، 12 مكررا ، 12 مكررا أ من هذا القانون .$m244$,'b9894d6f9a07c84c503a061f4988e015',DATE '2022-04-12',NULL,'active',21,2022,$m244$مادة مضافة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12). المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا توجد نسخة سابقة لأن المادة جديدة.$m244$),
(17,0,1,$m244$مع عدم الإخلال بأية عقوبة أشد ينص عليها قانون آخر ، يعاقب بذات العقوبة المنصوص عليها بالفقرة الأولي من المادة (16) من هذا القانون ، كل من تم قيده أو تجديد قيده بأي من السجلين المنصوص عليهما في المادة (2) من هذا القانون ، بناء علي بيانات غير صحيحة تعمد ذكرها ، أو بناء حجب بيانات أو معلومات أو سجلات أو مستندات كان من الواجب تقديمها أو الإدلاء بها ، وتعمد حجبها ، وذلك كله فيما يتعلق بتوافر شروط القيد بأي من السجلين المشار إليهما .
ويترتب علي صدور الحكم بالإدانة ، وفقا لحكم الفقرة الأولي من هذه المادة ، الحكم بحرمان المحكوم عليه من مزاولة النشاط مدة لا تجاوز سنتين ، وإلغاء القيد ، وسقوط الحق في استرداد التأمين ، وغلق المنشأة لمدة مساوية لمدة الحرمان من مزاولة النشاط .$m244$,'6c3493f2b06f88d6b46d6b76d6e7a29f',DATE '2022-04-12',NULL,'active',21,2022,$m244$استُبدل نص هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12). المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(18,0,1,$m244$يعاقب بالحبس مدة لا تزيد علي ستة أشهر وبغرامة لا تزيد علي خمسين ألف جنيه أو بإحدي هاتين العقوبتين ، كل وكيل أو وسيط تجاري أو سمسار عقاري مارس العمل بعد زوال أحد شروط القيد المنصوص عليها في أي من المادتين (3 ، 3 مكررا) من هذا القانون مع علمه بذلك ، فضلا عن الحكم بإلغاء القيد وسقوط الحق في استرداد التأمين .$m244$,'5de5d8eb9e34b17ad167ef5a20349cb2',DATE '2022-04-12',NULL,'active',21,2022,$m244$استُبدل نص هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12). المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(19,0,1,$m244$في الأحوال التي ترتكب فيها الجريمة بواسطة شخص اعتباري يعاقب المسئول عن الإدارة الفعلية لهذا الشخص الاعتباري بالعقوبات ذاتها المقررة عن الأفعال التي ترتكب بالمخالفة لأحكام هذا القانون ، إذا ثبت علمه بها ، وكانت الجريمة قد وقعت بسبب إخلاله بواجبات وظيفته . ويعاقب الشخص الاعتباري بغرامة لا تقل عن خمسين ألف جنيه ولا تجاوز مليون جنيه ، ويكون مسئولا بالتضامن عن الوفاء بما يحكم به من عقوبات مالية إذا كانت الجريمة التي وقعت بالمخالفة لأحكام هذا القانون قد ارتكبت من أحد العاملين به باسمه ولصالحه .$m244$,'20b41b78fccc0fb38cae7d4b56894060',DATE '2022-04-12',NULL,'active',21,2022,$m244$استُبدل نص هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12). المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(20,0,1,$m244$تنشر الأحكام النهائية الصادرة في الجرائم المنصوص عليها بالمواد أرقام (16 ، 17 ، 18 ، 19) من هذا القانون في جريدتين يوميتين واسعتي الانتشار يحددهما الحكم ، وبالنشرة التي تعدها الوزارة المختصة بسجلي الوكلاء والوسطاء التجاريين أو السماسرة العقاريين ، وذلك علي نفقة المحكوم عليه .$m244$,'bf6eca61c439b2f1722d2c71efaf5e8b',DATE '2022-04-12',NULL,'active',21,2022,$m244$استُبدل نص هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12). المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(20,1,1,$m244$يجوز للوزير المختص التصالح عن أي من الجرائم المنصوص عليها في هذا القانون قبل إقامة الدعوي الجنائية ، مقابل أداء مبلغ لا يقل عن مثلي الحد الأدني ولا يجاوز الحد الأقصي للغرامة المقررة ، ويجوز التصالح بعد إقامة الدعوي الجنائية وقبل صدور حكم فيها مقابل أداء مبلغ لا يقل عن أربعة أمثال الحد الأدني ولا يجاوز الحد الأقصي للغرامة المقررة ، كما يجوز التصالح بعد صدور الحكم الجنائي مقابل أداء مبلغ لا يقل عن الحد الأقصي للغرامة المقررة ولا يجاوز مثليه ، ويترتب علي التصالح انقضاء الدعوي الجنائية بالنسبة للجريمة التي تم التصالح في شأنها ، وتأمر النيابة العامة بوقف تنفيذ العقوبة إذا حصل التصالح أثناء تنفيذ العقوبة ولو كان ذلك بعد صيرورة الحكم باتا .$m244$,'e0c9cc960b5b35a14325595e55cb000c',DATE '2022-04-12',NULL,'active',21,2022,$m244$مادة مضافة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12). المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا توجد نسخة سابقة لأن المادة جديدة.$m244$),
(21,0,1,$m244$إذا خالف الوكيل التجارى أحكام الفقرة الأولى من المادة (10) من هذا القانون سقط حقه فى التأمين وعليه أن يؤدى تأمينا مضاعفا خلال ثلاثين يوما من تاريخ إخطاره بسقوط حقه فى التأمين بكتاب موصى عليه بعلم الوصول على آخر عنوان له أخطر به الإدارة المختصة بالسجل المشار إليه بالمادة (2) من هذا القانون .
وفى حالة تكرار المخالفة لحكم الفقرة الأولى من المادة (10) من هذا القانون يلغى القيد بقرار من وزير الاقتصاد ويسقط الحق فى استرداد التأمين المضاعف .$m244$,'8a1e2e9aaec69167c804fe4a7f7cf041',DATE '1983-05-05',NULL,'active',NULL,NULL,$m244$لا علامة تعديل على هذه المادة بالمصدر؛ تاريخ العمل بالأصل تقريبى (انظر ملاحظة تاريخ العمل). تنبيه للمراجعة البشرية: يرد «وزير الاقتصاد» فى الفقرة الثانية كما طُبع بالمصدر بلا علامة استبدال، بينما تنص ملاحظة المصدر على استبدال «الوزير المختص» بـ«وزير الاقتصاد» و«وزير الاقتصاد والتجارة الخارجية» بالقانون 21/2022.$m244$),
(22,0,1,$m244$يلغى قيد الوكيل أو الوسيط التجاري أو السمسار العقاري بقرار مسبب يصدره وزير الاقتصاد فى الأحوال الآتية :
(أ) مخالفة أحكام الفقرة الأولى من المادة (10) أو الفقرة الأولى من المادة (11) أو المادة (12) ، من هذا القانون ، ويترتب على إلغاء القيد فى هذه الحالة سقوط الحق فى استرداد التأمين .
(ب) إذا فقد الوكيل أو الوسيط التجاري أو السمسار العقاري شرطا من شروط القيد فى سجل الوكلاء التجاريين .
(ج) فى حالة وفاة الشخص الطبيعى أو انقضاء الشخص الاعتبارى .
(د) مخالفة أحكام المواد (11 مكررا ، 12 مكررا ، 12 مكررا "أ") من هذا القانون .$m244$,'26b469c26ead2dd21b04011049cd0ac1',DATE '2022-04-12',NULL,'active',21,2022,$m244$أُضيف البند (د) وعُدلت مسميات فى صدر المادة والبند (ب) بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12). تنبيه للمراجعة البشرية: يرد «وزير الاقتصاد» فى صدر المادة بلا علامة استبدال كما طُبع بالمصدر، بينما تنص ملاحظة المصدر على استبدال «الوزير المختص» بـ«وزير الاقتصاد» و«وزير الاقتصاد والتجارة الخارجية». المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(23,0,1,$m244$لا يجوز لمن صدر ضده حكم فى جريمة من الجرائم المنصوص عليها فى هذا القانون أن يعمل بأية صفة كانت لدى منشأة أو شركة تمارس أعمال الوكالة أو الوساطة التجارية أو السمسرة العقارية كما لا يجوز إعادة قيد من ألغى قيده بسجل الوكلاء والوسطاء التجاريون أو السماسرة العقاريين بالتطبيق لأحكام المادتين 21 ، 22 من هذا القانون إلا بعد مضى خمس سنوات على الأقل من تاريخ إلغاء القيد ، ولا يجوز له خلال هذه المدة أن يعمل بأية صفة كانت بمنشأة أو شركة تمارس أعمال الوكالة أو الوساطة التجارية أو السمسرة العقارية أو أن يشترك فى تأسيس أو إدارة شركة من الشركات التى تمارس أعمال الوكالة أو الوساطة التجارية أو السمسرة العقارية .$m244$,'ca1b34b8fab6407fa3cdf43324a3acd8',DATE '2022-04-12',NULL,'active',21,2022,$m244$عُدلت مسميات فى هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12) (علامة * فى المصدر: «السمسرة العقارية» و«السمسار العقارى» و«الوزير/الوزارة المختصة» ونحوها)؛ النص هنا هو الحالى كما طُبع بالمصدر، بما فيه صيغ الجمع المرفوعة مثل «التجاريون». المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(24,0,1,$m244$يعاقب تأديبيا العامل المسئول عن مخالفة حكم المادة (13) من هذا القانون .
فإذا ثبت أن المخالفة عمدية وبالتواطؤ مع الوكيل أو الوسيط التجاري أو السمسار العقاري التزم العامل مع الوكيل أو الوسيط التجاري أو السمسار العقاري بالتضامن ، بما يستحق من مبالغ الضريبة والتعويضات والغرامات كل ذلك مع عدم الإخلال بأية عقوبة أشد منصوص عليها بقانون آخر .$m244$,'9a2d97696cda5b788cef1b4c3d846eed',DATE '2022-04-12',NULL,'active',21,2022,$m244$عُدلت مسميات فى هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12) (علامة * فى المصدر: «السمسرة العقارية» و«السمسار العقارى» و«الوزير/الوزارة المختصة» ونحوها)؛ النص هنا هو الحالى كما طُبع بالمصدر، بما فيه صيغ الجمع المرفوعة مثل «التجاريون». المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(25,0,1,$m244$يتعين على الوكلاء التجاريين وعلى المكاتب المشار إليها بالمادة (7) من هذا القانون القائمين بالعمل عند نفاذ هذا القانون اتخاذ الإجراءات المنصوص عليها للقيد فى السجلات المعدة لذلك خلال المدة التى تحددها اللائحة التنفيذية .$m244$,'b9c67abd373498109066c9eae4d5e687',DATE '1983-05-05',NULL,'active',NULL,NULL,$m244$لا علامة تعديل على هذه المادة بالمصدر؛ تاريخ العمل بالأصل (1983-05-05) تقريبى: تسعة أشهر بعد نشر القانون بالجريدة الرسمية العدد 31 (تابع) فى 5 أغسطس 1982 بحسب مصدر ثانوى لا يتضمنه الملف المرفوع، ويُراجع بشرياً قبل الاستناد إليه.$m244$),
(26,0,1,$m244$يكون للعاملين القائمين على تنفيذ أحكام هذا القانون الذين يصدر بتحديدهم قرار من وزير العدل بعد الاتفاق مع الوزير المختص صفة مأمورى الضبط القضائى للكشف عن المخالفات التى تقع لأحكامه أو لأحكام اللائحة التنفيذية له .$m244$,'966de84a2d485818956c15a2b845f11d',DATE '1983-05-05',NULL,'active',NULL,NULL,$m244$لا علامة تعديل على هذه المادة بالمصدر؛ تاريخ العمل بالأصل (1983-05-05) تقريبى: تسعة أشهر بعد نشر القانون بالجريدة الرسمية العدد 31 (تابع) فى 5 أغسطس 1982 بحسب مصدر ثانوى لا يتضمنه الملف المرفوع، ويُراجع بشرياً قبل الاستناد إليه.$m244$),
(27,0,1,$m244$تراعى سرية البيانات التى يتضمنها سجل الوكلاء والوسطاء التجاريون أو السماسرة العقاريين ولا يجوز لغير القائمين على تنفيذ أحكام هذا القانون الاطلاع عليها ، وعلى كل من اطلع بحكم وظيفته على السجل أو البيانات المتعلقة به أو المكاتبات بين طالبى القيد أو تعديل البيانات أو التجديد وبين الإدارة المختصة بالسجل المشار إليه بالمادة (2) من هذا القانون أو بين هذه الإدارة والوكلاء أو الوسطاء التجاريون أو السماسرة العقاريين ، أن يراعى السرية التى تتوفر لهذه البيانات والمعلومات ويعاقب كل من يخالف ذلك بالعقوبة المنصوص عليها بالمادة 310 من قانون العقوبات .$m244$,'4db92ab667b5bd3a27de294006c8be73',DATE '2022-04-12',NULL,'active',21,2022,$m244$عُدلت مسميات فى هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12) (علامة * فى المصدر: «السمسرة العقارية» و«السمسار العقارى» و«الوزير/الوزارة المختصة» ونحوها)؛ النص هنا هو الحالى كما طُبع بالمصدر، بما فيه صيغ الجمع المرفوعة مثل «التجاريون». المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$),
(28,0,1,$m244$تصدر اللائحة التنفيذية لهذا القانون بقرار من الوزير المختص ، خلال أربعة أشهر من تاريخ نشره فى الجريدة الرسمية وتتضمن على وجه الخصوص تحديد مدة سريان القيد بحيث لا تقل عن سنة ولا تزيد على خمس سنوات .
كما تتضمن الجزاءات التى تترتب على مخالفة أحكامها بما لا يجاوز عقوبة الغرامة بحد أقصى مائة جنيه كما تحدد الحالات التى يجوز فيها بقرار من الوزير المختص شطب القيد بالسجل المشار إليه فى المادة (2) لمدة لا تجاوز ثلاث سنوات .$m244$,'3771109b9f42e42a6f2a015ed430d977',DATE '2022-04-12',NULL,'active',21,2022,$m244$عُدلت مسميات فى هذه المادة بـالقانون رقم 21 لسنة 2022 (الجريدة الرسمية العدد 14 مكرر (ج) فى 11 أبريل 2022، العمل به من 2022-04-12) (علامة * فى المصدر: «السمسرة العقارية» و«السمسار العقارى» و«الوزير/الوزارة المختصة» ونحوها)؛ النص هنا هو الحالى كما طُبع بالمصدر، بما فيه صيغ الجمع المرفوعة مثل «التجاريون». المصدر نسخة محدثة (تجميع) تعرض النص الحالى فقط ولا تتضمن نص ما قبل التعديل، فلا توجد نسخة سابقة محفوظة.$m244$);

DO $m244$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_vcnt int;
BEGIN
  IF (SELECT count(*) FROM m244_art WHERE md5(body) <> body_md5) <> 0 OR (SELECT count(*) FROM m244_ver WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[244] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m244_art) <> 42 OR (SELECT sum(char_length(body)) FROM m244_art) <> 22200 OR (SELECT count(*) FROM m244_ver) <> 42 THEN
    RAISE EXCEPTION '[244] عدد الصفوف أو النسخ أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=120 AND law_year=1982 AND kind='law';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%الوكالة التجارية%' THEN
    RAISE EXCEPTION '[244] يوجد مستند آخر برقم 120 لسنة 1982 (%): لا يُدمج هذا النص فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at, country_code, kind, governance_scope)
    VALUES (120, 1982, $t244$قانون رقم 120 لسنة 1982 بإصدار قانون تنظيم أعمال الوكالة التجارية وبعض أعمال الوساطة التجارية أو السمسرة العقارية (النسخة المحدثة بعد تعديله بالقانون رقم 21 لسنة 2022)$t244$, $t244$قانون تنظيم أعمال الوكالة التجارية$t244$, 'other', 'amended', NULL, DATE '1982-07-26', DATE '2022-04-12', 'EG', 'law', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m244_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
  SELECT a.id, m.version_no, m.body, m.eff, m.eff_to, m.status, m.am_no, m.am_yr, m.note
    FROM articles a JOIN m244_ver m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m244_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 42 THEN
    RAISE EXCEPTION '[244] عدد صفوف النص % بدل 42', v_cnt;
  END IF;
  SELECT count(*) INTO v_vcnt FROM article_versions v JOIN articles a ON a.id=v.article_id WHERE a.law_id=v_law;
  IF v_vcnt <> 42 THEN
    RAISE EXCEPTION '[244] عدد نسخ النص % بدل 42', v_vcnt;
  END IF;
  RAISE NOTICE '[244] قانون 120/1982: جديد=%, صفوف مضافة=%, نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m244$;
